from itertools import product

def solve():
    n = 6
    seq = [0]*12
    def bt(v):
        if v == 0:
            return seq[:]
        for i in range(12 - v - 1):
            if seq[i]==0 and seq[i+v+1]==0:
                seq[i]=v; seq[i+v+1]=v
                r = bt(v-1)
                if r: return r
                seq[i]=0; seq[i+v+1]=0
        return None
    return bt(n)

print(solve())
